async function callAIWithFallback(systemPrompt, userPrompt, opts = {}) {
  const providers = [
    { name: 'gemini', url: '/api/ai/gemini-compat', headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' }, body: { model: 'gemini-3.1-pro-preview', messages: [ { role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt } ], temperature: opts.temperature ?? 0.3, max_tokens: opts.maxTokens ?? 1200, ...(opts.json ? { response_format: { type: 'json_object' } } : {}) }, extract: (d) => d?.choices?.[0]?.message?.content },
    { name: 'anthropic', url: '/api/ai/anthropic', headers: { 'Content-Type': 'application/json' }, body: { model: 'claude-opus-4-6', max_tokens: opts.maxTokens ?? 1200, system: systemPrompt, messages: [{ role: 'user', content: userPrompt }] }, extract: (d) => d?.content?.[0]?.text },
    { name: 'openai', url: '/api/ai/openai', headers: { 'Content-Type': 'application/json' }, body: { model: 'gpt-4o', messages: [ { role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt } ], temperature: opts.temperature ?? 0.3, ...(opts.json ? { response_format: { type: 'json_object' } } : {}) }, extract: (d) => d?.choices?.[0]?.message?.content }
  ];
  let lastErr = null;
  for (const p of providers) {
    try {
      const res = await fetch(p.url, { method: 'POST', headers: p.headers, body: JSON.stringify(p.body) });
      if (!res.ok) { lastErr = new Error(`${p.name} HTTP ${res.status}`); continue; }
      const data = await res.json();
      const text = p.extract(data);
      if (!text || typeof text !== 'string') { lastErr = new Error(`${p.name} empty`); continue; }
      return { text, provider: p.name };
    } catch (e) { lastErr = e; }
  }
  throw new Error(`All AI providers failed: ${lastErr?.message || 'unknown'}`);
}

function parseAIJson(text) {
  if (!text || typeof text !== 'string') return null;
  let s = text.trim();
  if (s.startsWith('```')) s = s.replace(/```(json)?/gi, '').trim();
  try { return JSON.parse(s); } catch (_) {}
  const a = s.indexOf('{'), b = s.indexOf('[');
  let start = a < 0 ? b : b < 0 ? a : Math.min(a, b);
  if (start < 0) return null;
  const open = s[start], close = open === '{' ? '}' : ']';
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < s.length; i++) {
    const c = s[i];
    if (esc) { esc = false; continue; }
    if (c === '\\') { esc = true; continue; }
    if (c === '"') { inStr = !inStr; continue; }
    if (!inStr) { if (c === open) depth++; else if (c === close && --depth === 0) { try { return JSON.parse(s.slice(start, i + 1)); } catch (_) { return null; } } }
  }
  return null;
}

async function callAIForJSON(systemPrompt, userPrompt, opts = {}) {
  const jsonSys = systemPrompt + '\n\nRespond with ONLY a single valid JSON ' + (opts.array ? 'array' : 'object') + ' - no markdown, no fences, no prose. Begin with ' + (opts.array ? '[' : '{') + '.';
  for (let attempt = 0; attempt < 2; attempt++) {
    try { const { text } = await callAIWithFallback(jsonSys, userPrompt, { ...opts, json: true, temperature: 0.2 }); const parsed = parseAIJson(text); if (parsed != null) return parsed; } catch (_) {}
  }
  return opts.fallback ?? null;
}

const VS_INSTRUCTION = `Before answering, generate THREE distinct candidate responses, assign each a probability mass, then return the LOWEST-probability candidate that still earns >= 7/10 on quality and grounded relevance. Output ONLY the final chosen candidate in the requested JSON. Do not show intermediate candidates.`;
async function callAIWithVSForJSON(systemPrompt, userPrompt, opts = {}) {
  return callAIForJSON(`${systemPrompt}\n\n${VS_INSTRUCTION}`, userPrompt, { ...opts, temperature: 0.85 });
}

