const OverrideModal = ({ ask, onCancel, onConfirm }) => {
  const [reason, setReason] = useState('');
  const ref = useRef(null);
  useEffect(() => { ref.current && ref.current.focus(); const onKey = (e) => { if (e.key === 'Escape') onCancel(); }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey); }, []);
  return (
    <div className="scrim" role="dialog" aria-modal="true" aria-labelledby="ov-title">
      <div className="dialog">
        <h3 id="ov-title" className="title" style={{ fontSize:'18px', marginBottom:'12px' }}>Override: {ask.title}</h3>
        <p className="label" style={{ marginBottom:'16px' }}>A logged reason is required to override the orchestrator. This is recorded to the audit trail.</p>
        <label htmlFor="ov-reason" className="label" style={{ color:'var(--text)' }}>Override reason</label>
        <textarea id="ov-reason" ref={ref} value={reason} onChange={(e) => setReason(e.target.value)} style={{ width:'100%', height:'90px', padding:'10px', border:'1px solid var(--border)', borderRadius:'4px', margin:'8px 0 16px' }} />
        <div style={{ display:'flex', gap:'12px', justifyContent:'flex-end' }}>
          <button className="btn btn-secondary" onClick={onCancel}>Cancel</button>
          <button className="btn btn-primary" disabled={!reason.trim()} onClick={() => onConfirm(reason.trim())}>Log Override</button>
        </div>
      </div>
    </div>
  );
};

