          <div style={{ display:'flex', gap:'8px' }}>
            <button className="btn btn-secondary" onClick={() => onNavigate('sentiment_pulse')}>Sentiment Pulse</button>
            {!hasRsvped ? (
              <button className="btn btn-secondary" onClick={() => setHasRsvped(true)}><Calendar size={16} /> Trigger RSVP Intent</button>
            ) : (
              <button className="btn btn-primary" onClick={() => onNavigate('conflict_alert')}><AlertTriangle size={16} /> View Conflict Alert</button>
            )}
          </div>
        </div>
        <div className="timeline-ribbon" role="list" aria-label="Cross-team touchpoint timeline">
          {nodes.map(n => (
            <div key={n.id} role="listitem" tabIndex={0} className="touchpoint-node" style={{ borderLeftColor: CHANNEL_COLOR[n.channel] || 'var(--border)' }} title={`${n.owning_team} · ${n.channel} · ${n.type} · ${n.status}`}>
              <span className="label" style={{ fontSize:'12px' }}>{n.owning_team}</span>
              <span className="data" style={{ textTransform:'capitalize' }}>{n.channel} {n.type}</span>
              <span className="label" style={{ fontSize:'12px', textTransform:'capitalize' }}>{n.status}</span>
            </div>
          ))}
          {nodes.length === 0 && <div className="label">No touchpoints yet — trigger a signal to begin {donor.name}'s journey</div>}
          <AnimatePresence>
            {hasRsvped && donor.id === 'DNR-0001' && (
              <motion.div role="listitem" initial={prefersReduced() ? false : { opacity:0, scale:0.8 }} animate={{ opacity:1, scale:1 }} className="touchpoint-node intent" style={{ borderLeftColor:'var(--accent)' }}>
                <span className="label" style={{ color:'var(--accent)', fontSize:'12px' }}>Just now</span>
                <span className="data">RSVP: Showcase</span>
                <span className="label" style={{ fontSize:'12px' }}>High-intent signal</span>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </article>
  );
};

const ConflictAlert = ({ donor, onNavigate, setResolvedAsk, logEntries, addLog }) => {
  const [scores, setScores] = useState(null);
  const [fatigue, setFatigue] = useState(null);
  const [loading, setLoading] = useState(true);
  const [resolving, setResolving] = useState(false);
  const [overrideAsk, setOverrideAsk] = useState(null);
  const blockAll = donor.fatigue_score >= 70 && donor.sentiment_trend === 'cooling';
  useEffect(() => {
    let mounted = true; setLoading(true);
    (async () => {
      const [scoreRes, fatigueRes] = await Promise.all([
        callAIForJSON("Conflict resolver: score each queued touchpoint for relevance, recency overlap, and channel collision; rank which single ask should proceed.", `Donor: ${donor.name}. Competing: Khoury Invite, Annual Fund Ask, Athletics Text. Window 7d.`, { fallback: { ranked: [{ tp_id:'TP-1', relevance:92, reason:'High event affinity + fresh RSVP' }, { tp_id:'TP-2', relevance:48, reason:'Recent gift; fatigue weight high' }, { tp_id:'TP-3', relevance:39, reason:'Channel collision, low recency' }], recommended_let_through:'TP-1' } }),
        callAIForJSON("Fatigue modeler: compute a green/amber/red fatigue score and suppression recommendation.", `Donor: ${donor.name}. Fatigue ${donor.fatigue_score}. Trend ${donor.sentiment_trend}.`, { fallback: { score: donor.fatigue_score, band: donor.fatigue_score >= 70 ? 'red' : donor.fatigue_score >= 45 ? 'amber' : 'green', action: 'suppress' } })
      ]);
      if (mounted) { setScores(scoreRes); setFatigue(fatigueRes); setLoading(false); }
    })();
    return () => { mounted = false; };
  }, [donor]);
  const asks = [
    { id:'TP-1', title:'Khoury Showcase Invite', team:'Khoury Development', type:'invite' },
    { id:'TP-2', title:'Annual Fund Solicitation', team:'Annual Fund', type:'solicitation' },
    { id:'TP-3', title:'Season Ticket Renewal', team:'Athletics Engagement', type:'solicitation' }
  ];
  const handleResolve = (id) => {
    setResolving(true); setResolvedAsk(id);
    addLog({ ts: nowStamp(), actor:'Orchestrator', reason:'Annual Fund + Athletics suppressed; Khoury invite let through (relevance + fatigue).', conflict_id:'CNF-0001' });
    setTimeout(() => onNavigate('next_best_action'), 800);
  };
  const handleStewardship = () => {
    addLog({ ts: nowStamp(), actor:'Fatigue guardrail', reason:'Red fatigue + cooling sentiment — ALL solicitations blocked; routed to no-ask stewardship.', conflict_id:'CNF-0001' });
    onNavigate('sentiment_pulse');
  };
  const confirmOverride = (reason) => { addLog({ ts: nowStamp(), actor:'Priya (Annual Fund)', reason:`Override: ${reason}`, conflict_id:'CNF-0001' }); setOverrideAsk(null); };
  return (
    <article className="p-vignette-trio">
      <div>
        <h2 className="title" style={{ marginBottom:'8px' }}>Conflict Alert: 3 Asks Queued</h2>
        <p className="label" style={{ marginBottom:'16px' }}>{blockAll ? 'This donor is fatigued and cooling — every solicitation is blocked. Choose a no-ask stewardship gesture.' : 'Three teams queued asks within 7 days. Let only the highest-relevance, lowest-fatigue ask through.'}</p>
        {loading && <div role="status" aria-busy="true" style={{ marginBottom:'16px' }}><Skeleton height="40px" /><div style={{ height:'8px' }} /><Skeleton height="40px" width="80%" /><span className="label">Scoring conflicts…</span></div>}
        {!loading && (
        <div className="stacked-conflict-card">
          {asks.map((ask, i) => {
            const isRec = scores?.recommended_let_through === ask.id;
            const r = scores?.ranked.find(x => x.tp_id === ask.id);
            const score = r?.relevance || 0;
            const isDimmed = resolving && !isRec;
            const reduce = prefersReduced();
            return (
              <motion.div key={ask.id} className={`competing-ask-card ${isRec ? 'recommended' : ''} ${isDimmed ? 'dimmed' : ''}`}
                initial={reduce ? false : { x:0, y:0 }}
                animate={reduce ? {} : { x: resolving ? 0 : (i - 1) * 110, y: resolving ? (isRec ? 0 : 40) : (i === 1 ? -20 : 0), rotate: resolving ? 0 : (i - 1) * 4, zIndex: isRec ? 10 : 5 - i }}
                transition={{ type:'spring', stiffness:200, damping:22 }}>
                <div className="kicker">{ask.team}</div>
                <h3 style={{ fontSize:'18px', margin:'8px 0' }}>{ask.title}</h3>
                <div className="relevance-bar-container" role="meter" aria-valuenow={score} aria-valuemin={0} aria-valuemax={100} aria-label={`Relevance score for ${ask.title}: ${score} of 100`}>
                  <div className="relevance-bar-fill" style={{ width:`${score}%` }} />
                </div>
                <div style={{ fontSize:'13px', color:'var(--muted)', minHeight:'34px' }}>{r?.reason}</div>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginTop:'12px' }}>
                  <span className="label">Score: {score}</span>
                  {!resolving && isRec && !blockAll && <button className="btn btn-primary" onClick={() => handleResolve(ask.id)}>Let through</button>}
                  {!resolving && !isRec && <button className="btn btn-tertiary" style={{ fontSize:'14px' }} onClick={() => setOverrideAsk(ask)}>Override with reason</button>}
                </div>
              </motion.div>
            );
          })}
        </div>)}
        {blockAll && !loading && (
          <button className="btn btn-primary" style={{ marginTop:'16px' }} onClick={handleStewardship}>Route no-ask stewardship gesture</button>
        )}
        <div style={{ marginTop:'24px' }}><SuppressionLog entries={logEntries} /></div>
      </div>
      <div style={{ display:'flex', flexDirection:'column', gap:'24px' }}>
        <div className="p-dial" style={{ alignItems:'center' }}>
          <h3 className="title" style={{ fontSize:'18px' }}>Fatigue Risk</h3>
          <div className="gauge-arc"><div className="gauge-needle" style={{ transform:`rotate(${fatigue ? (fatigue.score / 100 * 180) - 90 : -90}deg)` }} /></div>
          <div style={{ textAlign:'center' }}>
            <div className="data" style={{ fontSize:'36px', color: fatigue?.band === 'red' ? 'var(--bad)' : fatigue?.band === 'amber' ? 'var(--warn)' : 'var(--text)' }}>{fatigue ? fatigue.score : '--'}</div>
            <div className="label">{fatigue ? `${fatigue.band} band` : 'loading'}</div>
          </div>
        </div>
        <div className="card p-counterfactual" style={{ background:'var(--rail)', color:'var(--surface)', borderColor:'var(--rail)' }}>
          <div style={{ display:'flex', gap:'12px', alignItems:'flex-start' }}>
            <ShieldAlert color="var(--warn)" />
            <div>
              <p style={{ fontWeight:500, marginBottom:'8px' }}>If all 3 sends proceed:</p>
              <p style={{ color:'rgba(255,255,255,0.75)' }}>85% predicted unsubscribe risk. If one sends: 12% risk.</p>
            </div>
          </div>
        </div>
      </div>
      {overrideAsk && <OverrideModal ask={overrideAsk} onCancel={() => setOverrideAsk(null)} onConfirm={confirmOverride} />}
    </article>
  );
};

