    .focused-action-card { background:var(--surface); border:1px solid var(--border); border-radius:8px; padding:32px; box-shadow:var(--shadow-soft); position:relative; overflow:hidden; }
    .chip-row { display:flex; gap:8px; margin-bottom:16px; flex-wrap:wrap; }
    .rationale-text { font-size:25px; line-height:1.4; margin-bottom:24px; color:var(--text); }
    .sparkline-container { height:120px; width:100%; border-bottom:1px solid var(--border); position:relative; margin:24px 0; display:flex; align-items:flex-end; gap:4px; padding-bottom:8px; }
    .week-grid { display:grid; grid-template-columns:repeat(5,1fr); gap:16px; }
    .grid-cell { background:var(--panel); border-radius:4px; padding:16px; text-align:center; transition:background .3s; }
    .grid-cell.conflict { background:rgba(216,19,45,0.1); border:1px solid var(--bad); }
    .grid-cell.resolved { background:rgba(29,110,100,0.1); border:1px solid var(--ok); }
    .p-kpi { display:grid; grid-template-columns:repeat(3,1fr); gap:24px; }
    .kpi-card { background:var(--surface); border:1px solid var(--border); border-radius:8px; padding:24px; }
    .kpi-value { font-size:36px; font-weight:400; margin:8px 0; }
    .log-row { display:flex; gap:12px; padding:10px 0; border-top:1px solid var(--border); font-size:13px; color:var(--muted); }
    .log-row .ts { font-variant-numeric:tabular-nums; min-width:140px; }
    .skeleton { background:linear-gradient(90deg,var(--panel) 25%,#E5E4DE 50%,var(--panel) 75%); background-size:200% 100%; animation:shimmer 1.5s infinite; border-radius:4px; }
    @keyframes shimmer { 0%{background-position:200% 0;} 100%{background-position:-200% 0;} }
    .scrim { position:fixed; inset:0; background:rgba(14,22,38,0.45); display:flex; align-items:center; justify-content:center; z-index:200; }
    .dialog { background:var(--surface); border-radius:8px; padding:32px; max-width:480px; width:90%; }
    .demo-controls { position:fixed; bottom:24px; right:24px; background:var(--surface); padding:16px; border-radius:8px; box-shadow:var(--shadow-soft); border:1px solid var(--border); z-index:100; display:flex; flex-direction:column; gap:8px; }
    textarea, select { font-family:inherit; }
    @media (max-width:860px) {
      .main-content { padding:24px 16px; }
      .p-vignette-trio, .p-kpi, .week-grid { grid-template-columns:1fr; }
      .stacked-conflict-card { min-height:auto; flex-direction:column; gap:16px; }
      .competing-ask-card { position:relative; width:100%; }
    }
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important; }
    }
  `;
  document.head.appendChild(style);
};

const Skeleton = ({ width = '100%', height = '20px' }) => (<div className="skeleton" style={{ width, height }} aria-hidden="true" />);
const Badge = ({ status, text, icon: Icon }) => {
  const colorMap = { ok:'var(--ok)', warn:'var(--warn)', bad:'var(--bad)', neutral:'var(--muted)' };
  const color = colorMap[status] || colorMap.neutral;
  return (<div className="badge">{Icon ? <Icon size={14} color={color} /> : <div className="badge-dot" style={{ backgroundColor: color }} />}<span style={{ color:'var(--text)' }}>{text}</span></div>);
};

const SuppressionLog = ({ entries }) => (
  <div className="card" aria-label="Suppression audit log">
    <div className="kicker" style={{ marginBottom:'12px' }}>Suppression Audit Log</div>
    {entries.length === 0 ? <p className="label">No suppression decisions logged yet for this donor.</p> :
      entries.map((e, i) => (
        <div className="log-row" key={i}>
          <span className="ts">{e.ts}</span>
          <span style={{ color:'var(--text)', minWidth:'90px' }}>{e.actor}</span>
          <span style={{ flex:1 }}>{e.reason}</span>
          <span>{e.conflict_id}</span>
        </div>
      ))}
  </div>
);

const OverrideModal = ({ ask, onCancel, onConfirm }) => {
  const [reason, setReason] = useState('');
  const ref = useRef(null);
  useEffect(() => { ref.current && ref.current.focus(); const onKey = (e) => { if (e.key === 'Escape') onCancel(); }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey); }, []);
  return (
    <div className="scrim" role="dialog" aria-modal="true" aria-labelledby="ov-title">
      <div className="dialog">
        <h3 id="ov-title" className="title" style={{ fontSize:'18px', marginBottom:'12px' }}>Override: {ask.title}</h3>
        <p className="label" style={{ marginBottom:'16px' }}>A logged reason is required to override the orchestrator. This is recorded to the audit trail.</p>
        <label htmlFor="ov-reason" className="label" style={{ color:'var(--text)' }}>Override reason</label>
        <textarea id="ov-reason" ref={ref} value={reason} onChange={(e) => setReason(e.target.value)} style={{ width:'100%', height:'90px', padding:'10px', border:'1px solid var(--border)', borderRadius:'4px', margin:'8px 0 16px' }} />
        <div style={{ display:'flex', gap:'12px', justifyContent:'flex-end' }}>
          <button className="btn btn-secondary" onClick={onCancel}>Cancel</button>
          <button className="btn btn-primary" disabled={!reason.trim()} onClick={() => onConfirm(reason.trim())}>Log Override</button>
        </div>
      </div>
    </div>
  );
};

const JourneyTimeline = ({ donor, onNavigate, hasRsvped, setHasRsvped }) => {
