  useEffect(() => {
    let mounted = true; setLoading(true);
    (async () => {
      const res = await callAIForJSON("Lifecycle classifier: read unified touchpoint history and signals, assign one of acquire/engage/steward/solicit/lapse, and recommend a stage-appropriate move.", `Donor: ${donor.name}, ${donor.lifetime_giving} LTV. Touchpoints: ${nodes.length}. Last signal: opened newsletter. Classify journey stage.`, { fallback: { stage: donor.journey_stage, confidence: 0.8, recommended_move: "Continue standard engagement" } });
      if (mounted) { setStageInfo(res); setLoading(false); }
    })();
    return () => { mounted = false; };
  }, [donor, nodes.length]);
  return (
    <article className="p-aspot aspot-edu">
      <header className="hero-ribbon">
        <h1>{donor.name}</h1>
        <div className="donor-summary-header">
          <span>Lifetime Giving: ${donor.lifetime_giving.toLocaleString()}</span>
          <span>College: {donor.college}</span>
          <span>Declared Pref: <span style={{ textTransform:'capitalize' }}>{donor.declared_pref}</span></span>
          {donor.opted_out && <Badge status="bad" text="Standing opt-out (binding)" icon={Lock} />}
        </div>
      </header>
      <div className="p-info-flow" style={{ marginTop:'32px' }}>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', flexWrap:'wrap', gap:'12px' }}>
          {loading ? <div role="status" aria-busy="true"><Skeleton width="140px" height="28px" /></div> : <Badge status="ok" text={`Stage: ${stageInfo?.stage || donor.journey_stage}`} />}
          <div style={{ display:'flex', gap:'8px' }}>
            <button className="btn btn-secondary" onClick={() => onNavigate('sentiment_pulse')}>Sentiment Pulse</button>
            {!hasRsvped ? (
              <button className="btn btn-secondary" onClick={() => setHasRsvped(true)}><Calendar size={16} /> Trigger RSVP Intent</button>
            ) : (
              <button className="btn btn-primary" onClick={() => onNavigate('conflict_alert')}><AlertTriangle size={16} /> View Conflict Alert</button>
            )}
          </div>
        </div>
        <div className="timeline-ribbon" role="list" aria-label="Cross-team touchpoint timeline">
