              <span className="label" style={{ fontSize:'12px', textTransform:'capitalize' }}>{n.status}</span>
            </div>
          ))}
          {nodes.length === 0 && <div className="label">No touchpoints yet — trigger a signal to begin {donor.name}'s journey</div>}
          <AnimatePresence>
            {hasRsvped && donor.id === 'DNR-0001' && (
              <motion.div role="listitem" initial={prefersReduced() ? false : { opacity:0, scale:0.8 }} animate={{ opacity:1, scale:1 }} className="touchpoint-node intent" style={{ borderLeftColor:'var(--accent)' }}>
                <span className="label" style={{ color:'var(--accent)', fontSize:'12px' }}>Just now</span>
                <span className="data">RSVP: Showcase</span>
                <span className="label" style={{ fontSize:'12px' }}>High-intent signal</span>
