      if (mounted) { setRec(res); setLoading(false); }
    })();
    return () => { mounted = false; };
  }, [donor]);
  const handleApprove = () => { setLocalApproved(true); setIsApproved(true); setTimeout(() => onNavigate('deconflicted_calendar'), 1000); };
  return (
    <article className="p-rec" style={{ maxWidth:'820px', margin:'0 auto' }}>
      <div className="focused-action-card">
        <AnimatePresence>{approved && !prefersReduced() && (<motion.div initial={{ x:'-100%' }} animate={{ x:'100%' }} transition={{ duration:0.6, ease:'easeInOut' }} style={{ position:'absolute', inset:0, background:'rgba(29,110,100,0.12)', zIndex:0 }} />)}</AnimatePresence>
        <div style={{ position:'relative', zIndex:1 }}>
          <div className="kicker" style={{ marginBottom:'16px' }}>Recommended Action</div>
          {loading ? (<div role="status" aria-busy="true"><Skeleton height="32px" width="80%" /><div style={{ height:'12px' }} /><Skeleton height="32px" width="60%" /><span className="label">Generating recommendation…</span></div>) : (<>
            <div className="chip-row"><Badge status="neutral" icon={Mail} text={rec?.channel} /><Badge status="neutral" icon={Clock} text={rec?.timing} /></div>
            <p className="rationale-text">{rec?.rationale}</p>
            <div style={{ display:'flex', gap:'16px', marginTop:'24px', flexWrap:'wrap' }}>
              <button className="btn btn-primary" onClick={handleApprove} disabled={approved}>{approved ? <><Check size={18} /> Approved</> : 'Approve & Schedule'}</button>
              <button className="btn btn-secondary" onClick={() => onNavigate('channel_preference_center')} disabled={approved}>Adjust Channel</button>
            </div>
          </>)}
        </div>
      </div>
      <div className="card" style={{ marginTop:'24px', background:'var(--panel)', borderStyle:'dashed' }}>
        <div style={{ display:'flex', alignItems:'center', gap:'8px', marginBottom:'16px', color:'var(--muted)' }}><Minus size={16} /><span className="label">Suppressed / Deferred Asks (logged)</span></div>
        <ul style={{ listStyle:'none', color:'var(--muted)' }}>
          <li style={{ padding:'8px 0', borderBottom:'1px solid var(--border)' }}>Annual Fund Solicitation — <span style={{ fontSize:'14px' }}>Fatigue guardrail exceeded</span></li>
          <li style={{ padding:'8px 0' }}>Athletics Season Tickets — <span style={{ fontSize:'14px' }}>Deferred 14 days · auto-release 2026-02-27</span></li>
        </ul>
      </div>
      <div style={{ marginTop:'24px' }}><SuppressionLog entries={logEntries} /></div>
    </article>
  );
};

