      <div style={{ display:'flex', gap:'12px', flexWrap:'wrap' }}>
        <button className="btn btn-primary" onClick={() => { addLog({ ts: nowStamp(), actor:'Aisha (Annual Fund)', reason:'Confirmed email channel; calls suppressed for donor.', conflict_id:'—' }); onNavigate('next_best_action'); }}>Confirm Email Recommendation</button>
      </div>
    </article>
  );
};

const SentimentPulse = ({ donor }) => {
  const [note, setNote] = useState('');
  const [trend, setTrend] = useState(donor.sentiment_trend);
  const [careFlag, setCareFlag] = useState(donor.sentiment_trend === 'cooling');
  const [analyzing, setAnalyzing] = useState(false);
  const handleAddNote = async () => {
    if (!note.trim()) return; setAnalyzing(true);
    const res = await callAIWithVSForJSON("Sentiment analyst: infer sentiment classification and update trajectory; raise a care flag on decline.", `Donor: ${donor.name}. New note: "${note}". Prior trend: ${trend}.`, { fallback: { new_trend:'rising', care_flag:false } });
    setTrend(res?.new_trend || 'stable'); setCareFlag(!!res?.care_flag); setNote(''); setAnalyzing(false);
  };
  return (
    <article className="p-chart" style={{ maxWidth:'820px', margin:'0 auto' }}>
      <div className="card" style={{ marginBottom:'32px' }}>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', flexWrap:'wrap', gap:'8px' }}>
          <h2 className="title">Sentiment Trajectory</h2>
          <Badge status={trend === 'cooling' ? 'warn' : 'ok'} text={`Trend: ${trend}`} icon={trend === 'cooling' ? TrendingDown : TrendingUp} />
        </div>
        {careFlag && <div role="status" style={{ marginTop:'12px' }}><Badge status="warn" text="Cooling — care flag raised. Solicitations blocked." icon={AlertTriangle} /></div>}
        <div className="sparkline-container">
          {[40,45,30,25,20,35,50,60].map((h, i) => (<motion.div key={i} initial={prefersReduced() ? false : { height:0 }} animate={{ height:`${h}%` }} transition={{ delay: prefersReduced() ? 0 : i * 0.08 }} style={{ flex:1, background: i > 4 && trend === 'rising' ? 'var(--ok)' : 'var(--muted)', opacity:0.6, borderRadius:'2px 2px 0 0' }} />))}
        </div>
      </div>
      <div className="card p-chat">
        <h3 className="label" style={{ marginBottom:'16px', color:'var(--text)' }}>Add interaction note</h3>
        <label htmlFor="sp-note" className="label" style={{ position:'absolute', left:'-9999px' }}>Call note</label>
        <textarea id="sp-note" value={note} onChange={(e) => setNote(e.target.value)} placeholder="e.g., Spoke about the new research center; very positive." style={{ width:'100%', height:'100px', padding:'12px', borderRadius:'4px', border:'1px solid var(--border)', marginBottom:'16px' }} />
        <button className="btn btn-secondary" onClick={handleAddNote} disabled={analyzing || !note.trim()} aria-busy={analyzing}>{analyzing ? 'Analyzing…' : 'Submit Note'}</button>
      </div>
    </article>
  );
};

const DeconflictedCalendar = ({ isOptimized, setIsOptimized, onNavigate }) => {
  const [running, setRunning] = useState(false);
  const handleOptimize = () => { setRunning(true); setTimeout(() => { setIsOptimized(true); setRunning(false); }, 1500); };
  const days = ['Mon','Tue','Wed','Thu','Fri'];
  const grid = Array(10).fill(0).map((_, i) => isOptimized ? { count: (i % 4) + 1, state:'resolved' } : { count: 6 + (i % 9), state: (i === 2 || i === 7) ? 'conflict' : 'normal' });
  return (
    <article className="p-cohort">
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:'32px', flexWrap:'wrap', gap:'12px' }}>
        <div><h2 className="title">Campaign Send Calendar</h2><p className="label" style={{ marginTop:'8px' }}>Cross-team scheduled touchpoints, next 14 days.</p></div>
        {!isOptimized ? <button className="btn btn-primary" onClick={handleOptimize} disabled={running} aria-busy={running}>{running ? 'Running optimizer…' : 'Run Deconfliction Optimizer'}</button> : <Badge status="ok" text="Zero same-week stacking" icon={Check} />}
      </div>
      <div className="card" style={{ marginBottom:'32px' }}>
        {running && <div role="status" aria-busy="true" style={{ marginBottom:'16px' }}><Skeleton height="60px" /><span className="label">Resolving collisions per donor…</span></div>}
        <div className="week-grid" style={{ marginBottom:'16px' }}>{days.map(d => <div key={d} className="label" style={{ textAlign:'center' }}>{d}</div>)}</div>
        <div className="week-grid">{grid.map((cell, i) => (<div key={i} className={`grid-cell ${cell.state === 'conflict' ? 'conflict' : cell.state === 'resolved' ? 'resolved' : ''}`}><div className="data" style={{ fontSize:'24px' }}>{cell.count}</div><div className="label" style={{ fontSize:'12px' }}>{cell.state === 'conflict' ? 'Collision' : cell.state === 'resolved' ? 'Clean' : 'Sends'}</div></div>))}</div>
      </div>
      {isOptimized && <button className="btn btn-primary" onClick={() => onNavigate('kpi_scorecard')}>Approve Deconflicted Plan</button>}
    </article>
  );
};

const KpiScorecard = () => {
  const [brief, setBrief] = useState(null);
  const [loadingBrief, setLoadingBrief] = useState(false);
  const [acked, setAcked] = useState(false);
  const handleOpenHandoff = async () => {
    setLoadingBrief(true);
    const res = await callAIWithVSForJSON("Handoff writer: generate a concise human-readable handoff brief with key context and a suggested first move.", "Donor: Marcus Bell. From: Athletics. To: Major Gifts. Sentiment cooling then warming.", { fallback: { brief:"Strong athletics ties; recent signals point to endowed-scholarship interest. Hold ticket asks 60 days while Major Gifts builds rapport.", key_context:['Email-preferred','Recent RSVP to research showcase'], open_asks:['Annual fund (deferred)'], suggested_first_move:"Invite to the Dean's research dinner." } });
    setBrief(res); setLoadingBrief(false);
  };
  return (
    <article className="p-kpi">
      <div style={{ gridColumn:'1 / -1', marginBottom:'16px' }}><h2 className="title">Shared Journey KPIs</h2><p className="label">Multi-touch attribution rolled up across all contributing teams.</p></div>
      {SEED_KPIS.map(kpi => (
        <div key={kpi.id} className="kpi-card">
          <div className="label">{kpi.kpi_name}</div>
          <div className="kpi-value">{kpi.kpi_name.includes('$') ? `$${kpi.value}K` : `${(kpi.value * 100).toFixed(0)}%`}</div>
          <div style={{ display:'flex', gap:'8px', alignItems:'center', fontSize:'14px', color:'var(--ok)' }}><TrendingUp size={16} /><span>vs target {kpi.kpi_name.includes('$') ? `$${kpi.target}K` : `${(kpi.target * 100).toFixed(0)}%`}</span></div>
          <div style={{ marginTop:'16px', height:'6px', background:'var(--panel)', borderRadius:'3px', display:'flex', overflow:'hidden' }} aria-label={`Contribution: ${kpi.contributing_teams.join(', ')}`}>
            <div style={{ width:'40%', background:'var(--accent)' }} title={kpi.contributing_teams[0]} />
            <div style={{ width:'35%', background:'var(--ok)' }} title={kpi.contributing_teams[1]} />
            <div style={{ width:'25%', background:'var(--muted)' }} title={kpi.contributing_teams[2]} />
          </div>
          <div className="label" style={{ fontSize:'12px', marginTop:'8px' }}>{kpi.contributing_teams.join(' · ')}</div>
        </div>
      ))}
      <div className="card p-chat" style={{ gridColumn:'1 / -1', marginTop:'32px' }}>
        <h3 className="title" style={{ fontSize:'21px', marginBottom:'24px' }}>Pending Cross-Team Handoffs</h3>
        <div className="card" style={{ background:'var(--panel)' }}>
          <div style={{ display:'flex', justifyContent:'space-between', marginBottom:'12px', flexWrap:'wrap', gap:'8px' }}><span className="label" style={{ color:'var(--text)' }}>Marcus Bell</span><Badge status="neutral" text="Athletics → Major Gifts" /></div>
          {loadingBrief ? <div role="status" aria-busy="true"><Skeleton height="60px" /><span className="label">Generating handoff brief…</span></div> : brief ? (
            <div>
              <p style={{ color:'var(--text)', marginBottom:'16px' }}>{brief.brief}</p>
              <div className="kicker" style={{ marginBottom:'8px' }}>Suggested first move</div>
              <p style={{ color:'var(--muted)', marginBottom:'16px' }}>{brief.suggested_first_move}</p>
              <button className="btn btn-primary" onClick={() => setAcked(true)} disabled={acked}>{acked ? <><Check size={16} /> Acknowledged</> : 'Acknowledge Handoff'}</button>
            </div>
          ) : <button className="btn btn-secondary" onClick={handleOpenHandoff}>Generate handoff brief</button>}
        </div>
      </div>
    </article>
  );
};

const App = () => {
  const [currentScreen, setCurrentScreen] = useState('journey_timeline');
  const [selectedDonorId, setSelectedDonorId] = useState('DNR-0001');
  const [hasRsvped, setHasRsvped] = useState(() => ssGet('hasRsvped', false));
  const [resolvedAsk, setResolvedAsk] = useState(() => ssGet('resolvedAsk', null));
  const [isApproved, setIsApproved] = useState(() => ssGet('isApproved', false));
  const [isOptimized, setIsOptimized] = useState(() => ssGet('isOptimized', false));
  const [logEntries, setLogEntries] = useState(() => ssGet('logEntries', []));
  useEffect(() => { injectStyles(); }, []);
  useEffect(() => { ssSet('hasRsvped', hasRsvped); }, [hasRsvped]);
  useEffect(() => { ssSet('resolvedAsk', resolvedAsk); }, [resolvedAsk]);
  useEffect(() => { ssSet('isApproved', isApproved); }, [isApproved]);
  useEffect(() => { ssSet('isOptimized', isOptimized); }, [isOptimized]);
  useEffect(() => { ssSet('logEntries', logEntries); }, [logEntries]);
  const addLog = useCallback((entry) => setLogEntries(prev => [entry, ...prev]), []);
  const donor = SEED_DONORS.find(d => d.id === selectedDonorId) || SEED_DONORS[0];
  const renderScreen = () => {
    switch (currentScreen) {
      case 'journey_timeline': return <JourneyTimeline donor={donor} onNavigate={setCurrentScreen} hasRsvped={hasRsvped} setHasRsvped={setHasRsvped} />;
      case 'conflict_alert': return <ConflictAlert donor={donor} onNavigate={setCurrentScreen} setResolvedAsk={setResolvedAsk} logEntries={logEntries} addLog={addLog} />;
      case 'next_best_action': return <NextBestAction donor={donor} onNavigate={setCurrentScreen} setIsApproved={setIsApproved} logEntries={logEntries} />;
      case 'channel_preference_center': return <ChannelPreference donor={donor} onNavigate={setCurrentScreen} addLog={addLog} />;
      case 'sentiment_pulse': return <SentimentPulse donor={donor} />;
      case 'deconflicted_calendar': return <DeconflictedCalendar isOptimized={isOptimized} setIsOptimized={setIsOptimized} onNavigate={setCurrentScreen} />;
      case 'kpi_scorecard': return <KpiScorecard />;
      default: return <div>Screen not found</div>;
    }
  };
  return (
    <div className="app-container" data-brand="nu">
      <header className="masthead">
        <div className="brand-lockup">
          <svg viewBox="0 0 64 53" fill="none" xmlns="http://www.w3.org/2000/svg" aria-label="Northeastern Advancement"><path d="M55.9355 15.9871C55.9355 8.40004 58.4903 5.92262 63.6 3.98714V2.70972H46.8774V3.94843C51.9871 5.88391 54.5419 8.36133 54.5419 15.9484V38.2065L19.1226 4.41294C17.4968 2.90327 17.071 2.74843 16.0258 2.74843H2.70969V3.98714C5.65162 4.29681 7.39356 5.10972 11.6129 9.21294L13.2387 10.7613V36.1549C13.2387 43.742 10.6839 46.2194 5.5742 48.1549V49.3936H22.2968V48.1549C17.1871 46.2194 14.6323 43.742 14.6323 36.1549V11.9226L54.6968 49.6646H55.9355V15.9871Z" fill="#C8102E"/></svg>
          <span className="brand-title">Advancement Choreographer</span>
        </div>
        <div style={{ display:'flex', alignItems:'center', gap:'12px', flexWrap:'wrap' }}>
          <span className="ctx-chip"><Info size={13} /> Institution: Northeastern · Synthetic demo data</span>
          <User size={20} color="var(--muted)" />
          <label htmlFor="donor-sel" style={{ position:'absolute', left:'-9999px' }}>Select donor</label>
          <select id="donor-sel" value={selectedDonorId} onChange={(e) => setSelectedDonorId(e.target.value)} style={{ padding:'8px', borderRadius:'4px', border:'1px solid var(--border)' }}>{SEED_DONORS.slice(0, 10).map(d => (<option key={d.id} value={d.id}>{d.name} ({d.id})</option>))}</select>
        </div>
      </header>
      <main className="main-content">
        <AnimatePresence mode="wait">
          <motion.div key={currentScreen} initial={prefersReduced() ? false : { opacity:0, y:10 }} animate={{ opacity:1, y:0 }} exit={prefersReduced() ? {} : { opacity:0, y:-10 }} transition={{ duration:0.2 }}>{renderScreen()}</motion.div>
        </AnimatePresence>
      </main>
      {/* PATTERN MANIFEST: p-aspot.aspot-edu, p-info-flow, p-vignette-trio, p-dial, p-counterfactual, p-rec, p-hitl, p-trail, p-chart, p-cohort, p-kpi, p-chat */}
      <div className="demo-controls">
        <div className="kicker" style={{ fontSize:'11px' }}>Demo Navigation</div>
        <label htmlFor="nav-sel" style={{ position:'absolute', left:'-9999px' }}>Navigate screens</label>
        <select id="nav-sel" value={currentScreen} onChange={(e) => setCurrentScreen(e.target.value)} style={{ padding:'8px', borderRadius:'4px', border:'1px solid var(--border)', fontSize:'14px' }}>
          <option value="journey_timeline">1. Journey Timeline</option>
          <option value="conflict_alert">2. Conflict Alert</option>
          <option value="next_best_action">3. Next Best Action</option>
          <option value="channel_preference_center">4. Channel Preference</option>
          <option value="sentiment_pulse">5. Sentiment Pulse</option>
          <option value="deconflicted_calendar">6. Deconflicted Calendar</option>
          <option value="kpi_scorecard">7. KPI Scorecard</option>
        </select>
      </div>
    </div>
  );
};

